import { randomUUID } from "node:crypto";

import { expect, expectStatus, test } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;

test.describe("review vendors", () => {
  test(
    "member submits a vendor with all documents extracted",
    { tag: "@REV-01" },
    async ({ apiAs }) => {
      // Arrange: signed in as the member persona
      const member = await apiAs("member");

      const vendor = await expectStatus<{ id: string; status: string }>(
        await member.post("/api/vendors", {
          data: {
            name: `Vendor ${randomUUID()}`,
            category: "services",
            contact_email: `ops-${randomUUID()}@example.test`,
          },
        }),
        201,
      );
      expect(vendor.status).toBe("draft");

      // Arrange: upload one document per kind and wait for each to be extracted
      for (const kind of KINDS) {
        const doc = await expectStatus<{ id: string }>(
          await member.post(`/api/vendors/${vendor.id}/documents`, {
            multipart: {
              kind,
              file: {
                name: `${kind}-${randomUUID()}.pdf`,
                mimeType: "application/pdf",
                buffer: Buffer.from("%PDF-1.4 test document"),
              },
            },
          }),
          201,
        );

        await expect
          .poll(
            async () =>
              (await expectStatus<{ status: string }>(await member.get(`/api/documents/${doc.id}`), 200)).status,
            { timeout: 30_000, intervals: [250, 500, 1000] },
          )
          .toBe("extracted");
      }

      // Act
      const response = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert
      const submitted = await expectStatus<{ id: string; status: string }>(response, 200);
      expect(submitted.id).toBe(vendor.id);
      expect(submitted.status).toBe("in_review");

      const trail = await expectStatus<{ items: { action: string }[] }>(
        await member.get(`/api/vendors/${vendor.id}/audit`),
        200,
      );
      expect(trail.items.map((event) => event.action)).toContain("vendor.submitted");
    },
  );
});
